/** A reference page generated during the build from a source in the repo. */
export interface GeneratedPage {
  /** The docs collection id, which is also its path: `docs/reference/rules/unknown-field`. */
  id: string;
  title: string;
  description?: string;
  /** Its place in an autogenerated sidebar group; lower comes first. */
  order?: number;
  /** A shorter sidebar label than the title. */
  label?: string;
  /** The repo file it is generated from, for the page's edit link. */
  source: string;
  /** The page's Markdown. */
  body: string;
}

/** Plain text from a source (a description, a default) for Markdown: `<` outside code spans escaped, so `<id>` isn't read as HTML. */
export const text = (plain: string): string =>
  plain
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 === 1 ? part : part.replace(/</g, "&lt;")))
    .join("");

/** Text for a Markdown table cell: one line, with pipes escaped. Cells built as Markdown pass through; pass plain text through `text()`. */
export const cell = (markdown: string): string => markdown.replace(/\r?\n+/g, " ").replace(/\|/g, "\\|").trim();

export const table = (head: readonly string[], rows: readonly (readonly string[])[]): string =>
  [`| ${head.join(" | ")} |`, `| ${head.map(() => "---").join(" | ")} |`, ...rows.map((r) => `| ${r.map(cell).join(" | ")} |`)].join("\n");

/** Joins Markdown blocks with one blank line between them. */
export const blocks = (...parts: (string | false | undefined)[]): string =>
  parts
    .filter((p): p is string => typeof p === "string" && p.trim() !== "")
    .map((p) => p.trim())
    .join("\n\n") + "\n";

/** A fenced code block, with a fence longer than any backtick run inside. */
export function fence(lang: string, code: string): string {
  const longest = Math.max(2, ...[...code.matchAll(/`+/g)].map((m) => m[0].length));
  const ticks = "`".repeat(longest + 1);
  return `${ticks}${lang}\n${code.trimEnd()}\n${ticks}`;
}

/** A Markdown file's leading `# Title`, and the rest. */
export function splitTitle(markdown: string): { title: string | undefined; rest: string } {
  const match = /^\s*# (.+)\n/.exec(markdown);
  return match ? { title: match[1]!.trim(), rest: markdown.slice(match[0].length) } : { title: undefined, rest: markdown };
}

/** Drops a leading `---` YAML frontmatter block. */
export const stripFrontmatter = (markdown: string): string => markdown.replace(/^---\n[\s\S]*?\n---\n/, "");
